def set_font(style, name='Times New Roman', size=12, bold=None, color=None):
    style.font.name = name
    style._element.rPr.rFonts.set(qn('w:eastAsia'), name)
    style.font.size = Pt(size)
    if bold is not None: style.font.bold = bold
    if color: style.font.color.rgb = RGBColor(*color)

normal = doc.styles['Normal']
set_font(normal)

def set_lang(style, lang='mk-MK'):
    rPr = style._element.get_or_add_rPr()
    lang_el = rPr.find(qn('w:lang'))
    if lang_el is None:
        lang_el = OxmlElement('w:lang'); rPr.append(lang_el)
    lang_el.set(qn('w:val'), lang)
    lang_el.set(qn('w:eastAsia'), lang)

set_lang(normal)
normal.paragraph_format.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
normal.paragraph_format.line_spacing = 1.5
normal.paragraph_format.first_line_indent = Cm(1.25)
normal.paragraph_format.space_after = Pt(5)
for stylename, size in [('Title', 20), ('Heading 1', 16), ('Heading 2', 13), ('Heading 3', 12)]:
    st = doc.styles[stylename]
    set_font(st, size=size, bold=True, color=(31, 55, 78))
    set_lang(st)
    st.paragraph_format.keep_with_next = True
    st.paragraph_format.first_line_indent = Cm(0)
    st.paragraph_format.space_before = Pt(12 if stylename != 'Title' else 0)
    st.paragraph_format.space_after = Pt(7)
    if stylename == 'Heading 1': st.paragraph_format.page_break_before = True
    if stylename in ('Heading 1','Heading 2'): st.paragraph_format.line_spacing = 1.15

def set_cell_shading(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)

def set_cell_margins(cell, top=100, start=110, bottom=100, end=110):
    tc=cell._tc; tcPr=tc.get_or_add_tcPr(); mar=OxmlElement('w:tcMar')
    for m,v in [('top',top),('start',start),('bottom',bottom),('end',end)]:
        el=OxmlElement('w:'+m); el.set(qn('w:w'),str(v)); el.set(qn('w:type'),'dxa'); mar.append(el)
    tcPr.append(mar)

def addp(text='', boldlead=None, italic=False, style=None, align=None):
    p=doc.add_paragraph(style=style)
    if align is not None: p.alignment=align
    if boldlead and text.startswith(boldlead):
        p.add_run(boldlead).bold=True; p.add_run(text[len(boldlead):])
    else:
        r=p.add_run(text); r.italic=italic
    return p

def heading(text, level=1):
    return doc.add_paragraph(text, style=f'Heading {level}')

def table(headers, rows, widths=None):
    t=doc.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i]; c.text=h; set_cell_shading(c,'1F374E'); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
        for p in c.paragraphs:
            p.alignment=WD_ALIGN_PARAGRAPH.CENTER
            for r in p.runs: r.bold=True; r.font.color.rgb=RGBColor(255,255,255); r.font.name='Times New Roman'; r.font.size=Pt(10)
        set_cell_margins(c)
    for ridx,row in enumerate(rows):
        cells=t.add_row().cells
        for i,val in enumerate(row):
            cells[i].text=str(val); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER; set_cell_margins(cells[i])
            if ridx%2: set_cell_shading(cells[i],'F1F4F7')
            for p in cells[i].paragraphs:
                p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.line_spacing=1.05; p.paragraph_format.space_after=Pt(1)
                p.alignment=WD_ALIGN_PARAGRAPH.LEFT
                for r in p.runs: r.font.name='Times New Roman'; r.font.size=Pt(9.5)
        if widths:
            for i,w in enumerate(widths): cells[i].width=Cm(w)
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

def caption(text):
    p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.space_after=Pt(8)
    r=p.add_run(text); r.italic=True; r.font.size=Pt(10)

def figure_placeholder(num, title, what, source, position, caption_text):
    p=doc.add_paragraph(); p.paragraph_format.first_line_indent=Cm(0); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_before=Pt(8); p.paragraph_format.space_after=Pt(5)
    r=p.add_run(f'[МЕСТО ЗА СЛИКА {num}]'); r.bold=True; r.font.size=Pt(13); r.font.color.rgb=RGBColor(31,55,78)
    for lead,txt in [('Назив:',title),('Што треба да прикажува:',what),('Извор:',source),('Позиција:',position)]:
        p=doc.add_paragraph(); p.paragraph_format.first_line_indent=Cm(0); p.paragraph_format.left_indent=Cm(1)
        p.paragraph_format.space_after=Pt(2); p.paragraph_format.line_spacing=1.1
        p.add_run(lead+' ').bold=True; p.add_run(txt)
    caption(f'Слика {num}. {caption_text}')

def page_field(p):
    r=p.add_run(); begin=OxmlElement('w:fldChar'); begin.set(qn('w:fldCharType'),'begin')
    instr=OxmlElement('w:instrText'); instr.set(qn('xml:space'),'preserve'); instr.text=' PAGE '
    sep=OxmlElement('w:fldChar'); sep.set(qn('w:fldCharType'),'separate'); txt=OxmlElement('w:t'); txt.text='1'
    end=OxmlElement('w:fldChar'); end.set(qn('w:fldCharType'),'end')
    for e in [begin,instr,sep,txt,end]: r._r.append(e)

